//! Repository generators and drift checks (D94).
//!
//! ```text
//! cargo xtask gen --mode write    regenerate every generated file
//! cargo xtask gen --mode check    fail if a generated file is out of date (CI)
//! cargo xtask man --out-dir DIR   write man pages (release builds)
//! ```
//!
//! Generated files: the CLI reference, the bibliography and the citation data of the
//! documentation site, the BibTeX database the site offers, `CITATION.cff`, `.zenodo.json` and
//! the "How to cite" section of `README.md` (between its `cite:start`/`cite:end` markers).
//! Every one of them is derived from the program itself (`crates/dima/src/cli`) or from the
//! citation registry (`crates/dima-core/src/citations.rs`), so they cannot drift from the code. Check mode also
//! compares the citation registry with the stored Crossref snapshot and the schema versions with
//! the code.

mod bibliography;
mod checks;
mod cli_reference;
mod markdown;
mod readme;
mod zenodo;

use std::path::{Path, PathBuf};
use std::process::ExitCode;

/// A file the generators own: its path from the repository root and its content.
struct Generated {
    path: &'static str,
    content: String,
}

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("xtask lives in the repository root")
        .to_path_buf()
}

/// Every generated file.
fn generated() -> Vec<Generated> {
    vec![
        Generated {
            path: "docs/src/content/docs/reference/cli.md",
            content: cli_reference::render(),
        },
        Generated {
            path: "docs/src/content/docs/reference/bibliography.md",
            content: bibliography::page(),
        },
        Generated {
            path: "docs/src/references.json",
            content: bibliography::references_json(),
        },
        Generated {
            path: "docs/src/references.bib",
            content: bibliography::bibtex(),
        },
        Generated {
            path: "CITATION.cff",
            content: format!(
                "# Generated by `cargo xtask gen` from crates/dima-core/src/citations.rs; do not edit.\n{}",
                dima_core::citations::cff_document(
                    dima_core::citations::SOFTWARE_VERSION,
                    &bibliography::method_references(),
                )
            ),
        },
        Generated {
            path: ".zenodo.json",
            content: zenodo::render(),
        },
        Generated {
            path: "README.md",
            content: readme::with_citation(&root()),
        },
    ]
}

/// Writes (`write = true`) or compares the generated files; returns the problems found.
fn gen_files(write: bool) -> Vec<String> {
    let root = root();
    let mut problems = Vec::new();
    for g in generated() {
        let path = root.join(g.path);
        let current = std::fs::read_to_string(&path).ok();
        if current.as_deref() == Some(g.content.as_str()) {
            continue;
        }
        if write {
            if let Some(dir) = path.parent() {
                if let Err(e) = std::fs::create_dir_all(dir) {
                    problems.push(format!("cannot create {}: {e}", dir.display()));
                    continue;
                }
            }
            match std::fs::write(&path, &g.content) {
                Ok(()) => eprintln!("wrote {}", g.path),
                Err(e) => problems.push(format!("cannot write {}: {e}", g.path)),
            }
        } else {
            problems.push(format!(
                "{} is out of date (run `cargo xtask gen --mode write`)",
                g.path
            ));
        }
    }
    problems
}

/// Generated files plus every consistency check.
fn run_gen(write: bool) -> Vec<String> {
    let mut problems = gen_files(write);
    problems.extend(checks::all(&root()));
    problems
}

fn man(out_dir: &Path) -> Result<(), String> {
    use clap::CommandFactory;
    std::fs::create_dir_all(out_dir).map_err(|e| format!("{}: {e}", out_dir.display()))?;
    let mut cmd = dima::cli::args::Cli::command();
    cmd.build();
    let mut pages = vec![("dima".to_owned(), cmd.clone())];
    for sub in cmd.get_subcommands().filter(|s| s.get_name() != "help") {
        let name = format!("dima-{}", sub.get_name());
        pages.push((
            name.clone(),
            sub.clone().bin_name(format!("dima {}", sub.get_name())),
        ));
    }
    for (name, page) in pages {
        let mut buf = Vec::new();
        clap_mangen::Man::new(page)
            .title(name.to_uppercase())
            .section("1")
            .render(&mut buf)
            .map_err(|e| format!("{name}: {e}"))?;
        let page = no_hyphenation(&String::from_utf8_lossy(&buf));
        let path = out_dir.join(format!("{name}.1"));
        std::fs::write(&path, page).map_err(|e| format!("{}: {e}", path.display()))?;
        eprintln!("wrote {}", path.display());
    }
    Ok(())
}

/// Turns off hyphenation after the title line (`.nh`), so groff never splits URLs, DOIs or
/// option names across lines (D107).
fn no_hyphenation(page: &str) -> String {
    let mut out = String::with_capacity(page.len() + 4);
    let mut done = false;
    for line in page.split_inclusive('\n') {
        out.push_str(line);
        if !done && line.starts_with(".TH ") {
            out.push_str(".nh\n");
            done = true;
        }
    }
    out
}

const USAGE: &str =
    "usage: cargo xtask gen --mode write|check\n       cargo xtask man --out-dir DIR";

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let args: Vec<&str> = args.iter().map(String::as_str).collect();
    match args.as_slice() {
        ["gen", "--mode", mode @ ("write" | "check")] => {
            let problems = run_gen(*mode == "write");
            for p in &problems {
                eprintln!("error: {p}");
            }
            if problems.is_empty() {
                if *mode == "check" {
                    eprintln!("generated files and checks are up to date");
                }
                ExitCode::SUCCESS
            } else {
                ExitCode::FAILURE
            }
        }
        ["man", "--out-dir", dir] => match man(Path::new(dir)) {
            Ok(()) => ExitCode::SUCCESS,
            Err(e) => {
                eprintln!("error: {e}");
                ExitCode::FAILURE
            }
        },
        _ => {
            eprintln!("{USAGE}");
            ExitCode::from(2)
        }
    }
}

#[cfg(test)]
mod tests {
    /// The thin test that keeps `cargo test --workspace` honest about generated files (D94).
    #[test]
    fn generated_files_are_up_to_date() {
        let problems = super::run_gen(false);
        assert!(problems.is_empty(), "{problems:#?}");
    }

    #[test]
    fn man_pages_render() {
        let dir = std::env::temp_dir().join(format!("dima-xtask-man-{}", std::process::id()));
        super::man(&dir).unwrap();
        let page = std::fs::read_to_string(dir.join("dima-analyze.1")).unwrap();
        assert!(page.contains("kmer"), "{page}");
        let th = page.find("\n.TH ").unwrap();
        assert!(page[th..].split('\n').nth(2) == Some(".nh"), "{page}");
        for name in [
            "dima",
            "dima-analyze",
            "dima-view",
            "dima-hcs",
            "dima-cite",
            "dima-completions",
        ] {
            std::fs::remove_file(dir.join(format!("{name}.1"))).unwrap();
        }
        std::fs::remove_dir(&dir).unwrap();
    }
}
